     1→'use client';
     2→
     3→import { createContext, useContext, useState, useEffect, ReactNode } from 'react';
     4→
     5→type Theme = 'light' | 'dark';
     6→
     7→const ThemeContext = createContext<{
     8→  theme: Theme;
     9→  toggleTheme: () => void;
    10→}>({ theme: 'light', toggleTheme: () => {} });
    11→
    12→export function useTheme() {
    13→  return useContext(ThemeContext);
    14→}
    15→
    16→export function ThemeProvider({ children }: { children: ReactNode }) {
    17→  const [theme, setTheme] = useState<Theme>('light');
    18→
    19→  useEffect(() => {
    20→    const savedTheme = localStorage.getItem('theme') as Theme;
    21→    if (savedTheme) {
    22→      setTheme(savedTheme);
    23→    }
    24→  }, []);
    25→
    26→  useEffect(() => {
    27→    document.documentElement.setAttribute('data-theme', theme);
    28→  }, [theme]);
    29→
    30→  const toggleTheme = () => {
    31→    const newTheme = theme === 'light' ? 'dark' : 'light';
    32→    setTheme(newTheme);
    33→    localStorage.setItem('theme', newTheme);
    34→  };
    35→
    36→  return (
    37→    <ThemeContext.Provider value={{ theme, toggleTheme }}>
    38→      <div data-testid="theme-wrapper" id="theme-wrapper" className={`min-h-screen ${theme === 'dark' ? 'bg-[#1a1a1a] text-white' : 'bg-white text-black'}`}>
    39→        {children}
    40→      </div>
    41→    </ThemeContext.Provider>
    42→  );
    43→}
